TYPE E_GateState
    (* 四状态枚举 *)
    TX_NAMESPACE.E_GateState : (
        IDLE    := 0,
        OPENING := 1,
        CLOSING := 2,
        FAULT   := 3
    );
END_TYPE

FUNCTION_BLOCK FB
VAR_INPUT
    openBtn    : BOOL;  (* 开门按钮，上升沿有效 *)
    closeBtn   : BOOL;  (* 关门按钮，上升沿有效 *)
    openLimit  : BOOL;  (* 开到位限位开关 *)
    closeLimit : BOOL;  (* 关到位限位开关 *)
    obstacle   : BOOL;  (* 防夹物体检测 *)
END_VAR
VAR_OUTPUT
    motorUp   : BOOL;  (* 电机上升输出 *)
    motorDown : BOOL;  (* 电机下降输出 *)
    errorFlag : BOOL;  (* 故障锁存标志 *)
END_VAR
VAR
    state       : E_GateState := IDLE;  (* 当前状态 *)
    prevOpenBtn : BOOL := FALSE;        (* 上一周期开门按钮状态 *)
    prevCloseBtn: BOOL := FALSE;        (* 上一周期关门按钮状态 *)
    edgeOpen    : BOOL;                 (* 开门按钮上升沿 *)
    edgeClose   : BOOL;                 (* 关门按钮上升沿 *)
END_VAR

    (* 计算上升沿 *)
    edgeOpen  := openBtn AND NOT prevOpenBtn;
    edgeClose := closeBtn AND NOT prevCloseBtn;

    CASE state OF
        IDLE:
            motorUp   := FALSE;
            motorDown := FALSE;
            errorFlag := FALSE;
            (* 检测开门/关门按钮上升沿，且未到对应限位 *)
            IF edgeOpen AND NOT openLimit THEN
                state := OPENING;
            ELSIF edgeClose AND NOT closeLimit THEN
                state := CLOSING;
            END_IF

        OPENING:
            (* 安全互锁：检测到障碍立即停机并进入FAULT *)
            IF obstacle THEN
                motorUp   := FALSE;
                state     := FAULT;
            ELSE
                motorUp := NOT openLimit;
                IF openLimit THEN
                    motorUp := FALSE;
                    state   := IDLE;
                END_IF
            END_IF

        CLOSING:
            (* 安全互锁：检测到障碍立即停止并反向开门 *)
            IF obstacle THEN
                motorDown := FALSE;
                state     := OPENING;
            ELSE
                motorDown := NOT closeLimit;
                IF closeLimit THEN
                    motorDown := FALSE;
                    state     := IDLE;
                END_IF
            END_IF

        FAULT:
            (* 故障锁存，电机不得动作 *)
            motorUp   := FALSE;
            motorDown := FALSE;
            errorFlag := TRUE;
            (* 仅当 openBtn 与 closeBtn 同时按下时解除故障 *)
            IF openBtn AND closeBtn THEN
                errorFlag := FALSE;
                state     := IDLE;
            END_IF
    END_CASE

    (* 更新历史状态以供下一周期边沿检测 *)
    prevOpenBtn  := openBtn;
    prevCloseBtn := closeBtn;
END_FUNCTION_BLOCK

TYPE E_GateState
    (IDLE:=0, OPENING:=1, CLOSING:=2, FAULT:=3);
END_TYPE

FUNCTION_BLOCK FB
VAR_INPUT
    openBtn    : BOOL;
    closeBtn   : BOOL;
    openLimit  : BOOL;
    closeLimit : BOOL;
    obstacle   : BOOL;
END_VAR
VAR_OUTPUT
    motorUp   : BOOL;
    motorDown : BOOL;
    errorFlag : BOOL;
END_VAR
VAR
    state        : E_GateState := E_GateState.IDLE;
    prevOpenBtn  : BOOL := FALSE;
    prevCloseBtn : BOOL := FALSE;
    edgeOpen     : BOOL;
    edgeClose    : BOOL;
END_VAR

    edgeOpen  := openBtn AND NOT prevOpenBtn;
    edgeClose := closeBtn AND NOT prevCloseBtn;

    CASE state OF
        E_GateState.IDLE:
            motorUp   := FALSE;
            motorDown := FALSE;
            errorFlag := FALSE;
            IF edgeOpen AND NOT openLimit THEN
                state := E_GateState.OPENING;
            ELSIF edgeClose AND NOT closeLimit THEN
                state := E_GateState.CLOSING;
            END_IF

        E_GateState.OPENING:
            IF obstacle THEN
                motorUp   := FALSE;
                state     := E_GateState.FAULT;
            ELSE
                IF openLimit THEN
                    motorUp := FALSE;
                    state   := E_GateState.IDLE;
                ELSE
                    motorUp := TRUE;
                END_IF
            END_IF

        E_GateState.CLOSING:
            IF obstacle THEN
                motorDown := FALSE;
                state     := E_GateState.OPENING;
            ELSE
                IF closeLimit THEN
                    motorDown := FALSE;
                    state     := E_GateState.IDLE;
                ELSE
                    motorDown := TRUE;
                END_IF
            END_IF

        E_GateState.FAULT:
            motorUp   := FALSE;
            motorDown := FALSE;
            errorFlag := TRUE;
            IF openBtn AND closeBtn THEN
                errorFlag := FALSE;
                state     := E_GateState.IDLE;
            END_IF
    END_CASE

    prevOpenBtn  := openBtn;
    prevCloseBtn := closeBtn;
END_FUNCTION_BLOCK
